# Generated by scripts/homebrew/formula.mjs in https://github.com/EvanZhang008/open-walnut for open-walnut 0.6.9.
class OpenWalnut < Formula
  desc "Personal AI: tasks, notes and Claude Code sessions on your own machine"
  homepage "https://github.com/EvanZhang008/open-walnut"
  version "0.6.9"
  license "MIT"

  on_macos do
    on_arm do
      url "https://github.com/EvanZhang008/open-walnut/releases/download/v0.6.9/open-walnut-0.6.9-darwin-arm64.tar.gz", using: :nounzip
      sha256 "9aa20f806a9919293adf105d228c8fe85062a4ea1ab23dcfaff54a98f5a49fa2"
    end
    on_intel do
      url "https://github.com/EvanZhang008/open-walnut/releases/download/v0.6.9/open-walnut-0.6.9-darwin-x64.tar.gz", using: :nounzip
      sha256 "4220223ccf7a542449b682bb2cb5915733244e215518110c1289a9df6ecfb33a"
    end
  end

  on_linux do
    on_arm do
      url "https://github.com/EvanZhang008/open-walnut/releases/download/v0.6.9/open-walnut-0.6.9-linux-arm64.tar.gz", using: :nounzip
      sha256 "ccc251217859570aa6ab122787f4be581240c0a3e339f73919cc2c92f3f3b7d5"
    end
    on_intel do
      url "https://github.com/EvanZhang008/open-walnut/releases/download/v0.6.9/open-walnut-0.6.9-linux-x64.tar.gz", using: :nounzip
      sha256 "3c877c3517775a56147a0e85a0865b2759589f7b4f4aa05d22c864d2d2c3e4b8"
    end
  end

  def install
    libexec.install Dir["open-walnut-*.tar.gz"].first => "open-walnut.tar.gz"
    # Scripts, not links: the cleaner drops a link whose target is not there yet.
    bin.write_exec_script libexec/"app/bin/walnut", libexec/"app/bin/open-walnut"
  end

  # After Homebrew's install-name pass over the keg, which the archive must skip.
  # The packed copy goes once unpacked, so running these again changes nothing.
  post_install_steps do
    if_path_exists "open-walnut.tar.gz", base: :libexec do
      remove "app", base: :libexec, recursive: true
      mkdir_p "app", base: :libexec
      run "tar", args: ["-xzf", "{{libexec}}/open-walnut.tar.gz", "-C", "{{libexec}}/app", "--strip-components=1"],
                 writable_paths: ["app"], writable_base: :libexec
      remove "open-walnut.tar.gz", base: :libexec
    end
  end

  def caveats
    <<~EOS
      Start it with:
        walnut web
      Walnut keeps itself up to date: it installs new releases when it starts.
      Its sessions run Claude Code: https://claude.com/product/claude-code
    EOS
  end

  test do
    assert_match version.to_s, shell_output("#{bin}/walnut --version")
  end
end
